function renderBusiness(){
 const b=bizById(route.id);if(!accessibleRecord(b))return unavailable();const p=image(b.photos?.[0]),unclaimed=b.claimed===false,susp=!!b.suspended;
 actionsBar(`${iconBtn(b.saved?'bookmark':'bookmark_border','save-biz',b.id,b.saved?'Remover negócio dos salvos':'Salvar negócio',`aria-pressed="${!!b.saved}"`)}${iconBtn('share','share',`negocio|${b.id}`,'Compartilhar negócio')}${b.mine?btn('Editar página','edit-biz',b.id,'filled','edit'):susp?'':unclaimed?btn(b.myInd?'Convidar responsável':'Também indico',b.myInd?'invite-owner':'recommend-biz',b.id,'filled',b.myInd?'send':'thumb_up'):btn('Pedir orçamento','quote',b.id,'filled','request_quote')}`);
 const asks=state.asks.filter(q=>!q.hidden&&!q.hiddenByMe&&(q.mine||!isBlocked(q.who))&&q.city===b.city&&q.answers.some(a=>a.biz===b.id));
 let h=`<div class="detail-layout"><div><div class="detail-hero">${p?`<img src="${p}" alt="${esc(b.name)}"><button type="button" class="hero-zoom" data-action="lightbox" data-value="biz">${icon('image')}Ver foto</button>`:''}<span class="pill">${esc(isSpon(b)?'Patrocinado':b.cat)}</span></div>${b.demo?'<p class="labelled-example">Foto ilustrativa do negócio de exemplo.</p>':''}<div class="detail-title"><h1>${esc(b.name)}</h1><p class="small muted">${esc(b.cat)}${b.specs?.length?` · ${esc(b.specs.join(', '))}`:''} · ${esc(b.city)}</p></div>${susp?`<div class="context-strip readonly" style="margin-top:0" role="status">${icon('lock')}<span class="grow"><b>Página suspensa pela moderação</b><br>Ela não aparece no catálogo nem na busca, e não recebe pedidos.</span></div>`:''}${unclaimed?`<div class="context-strip readonly" style="margin-top:0">${icon('hourglass_top')}<span>Esta página foi indicada por um membro. O responsável ainda não confirmou as informações.</span></div>`:''}${b.disc?`<div class="business-benefit">${icon('sell')} <b>Benefício para a comunidade</b><br>${esc(b.disc)}</div>`:''}<section class="section">${sectionTitle('Como pode ajudar')}<p class="detail-copy">${esc(b.bio||'O responsável poderá completar a descrição quando assumir a página.')}</p></section><section class="section">${sectionTitle('Serviços')}<md-chip-set>${b.svc.map(s=>`<md-assist-chip label="${esc(s)}">${icon('check','icon')}</md-assist-chip>`).join('')}</md-chip-set>${!b.svc.length?'<p class="small muted">Serviços ainda não informados pelo responsável.</p>':''}</section><section class="section">${sectionTitle('Onde atende')}<md-chip-set>${b.hoods.map(s=>`<md-assist-chip label="${esc(s)}">${icon('location_on','icon')}</md-assist-chip>`).join('')}</md-chip-set></section><section class="section">${sectionTitle('O que a comunidade diz')}<div class="stack">${(b.says||[]).map(x=>`<div class="answer"><div class="row"><span class="avatar">${esc(x[0])}</span><b>${esc(x[2])}</b></div><p>${esc(x[3])}</p></div>`).join('')||'<p class="small muted">Os relatos aparecem quando um membro indica este negócio.</p>'}</div></section>${asks.length?`<section class="section">${sectionTitle('Ver a origem das indicações')}<div class="list">${asks.map(questionRow).join('')}</div></section>`:''}</div><aside class="detail-aside"><div class="facts" style="grid-template-columns:1fr 1fr"><div class="fact fact-proof">${countHtml(b.recN)}<span>indicações da comunidade</span>${avatarStack(b.says,b.recN||0)}</div><div class="fact">${icon('schedule')}<span>${esc(b.hours||'Confirme com o responsável')}</span></div></div>${b.owner?`<div class="seller">${icon('verified_user')}<span class="small grow">${esc(b.owner)}</span>${iconBtn('info','verified-info','','O que o selo “verificado” significa','aria-haspopup="dialog"')}</div>`:''}${b.mine?businessMetrics(b):`<div class="stack">${!unclaimed&&!susp&&b.whatsapp?btn('WhatsApp','whatsapp',b.id,'outlined','call'):''}${!unclaimed&&!susp&&b.instagram?btn('Instagram','instagram',b.id,'outlined'):''}${!unclaimed&&!susp&&b.website?btn('Site','website',b.id,'outlined','open_in_new'):''}${susp?'':unclaimed?btn('Sou o responsável','claim-biz',b.id,'outlined','storefront'):btn('Indicar este negócio','recommend-biz',b.id,'outlined','thumb_up')}${btn('Denunciar página','report',`biz|${b.id}`,'text','flag')}</div>`}</aside></div>`;return h;
}
function businessMetrics(b){const ts=state.threads.filter(t=>t.about.type==='biz'&&t.about.id===b.id);return `<section class="section" style="margin-top:16px">${sectionTitle('Resultados da sua página')}<div class="metric-grid"><div class="metric"><b>${b.views||0}</b><span>visitas</span></div><div class="metric"><b>${ts.length}</b><span>pedidos de contato</span></div><div class="metric"><b>${ts.filter(t=>t.msgs.some(m=>m.me)).length}</b><span>conversas respondidas</span></div></div><p class="small muted" style="margin-top:12px">Plano ${state.subscription.tier==='free'?'grátis':'de teste'} · os indicadores contam as ações realizadas nesta versão.</p>${planStatusHtml()}<div class="stack" style="margin-top:16px">${btn('Ver pedidos recebidos','biz-leads',b.id,'outlined','inbox')}${btn('Conhecer os planos','plans','','tonal','trending_up')}${btn('Copiar link da página','share',`negocio|${b.id}`,'text','link')}</div></section>`;}
